<?php
namespace SignalPilot\Services; class ReportService{public static function metrics(array $trades,array $opps):array{$closed=array_values(array_filter($trades,fn($t)=>($t['status']??'')==='closed'));$wins=array_values(array_filter($closed,fn($t)=>(float)($t['profit_loss']??0)>0));$loss=array_values(array_filter($closed,fn($t)=>(float)($t['profit_loss']??0)<0));$sum=fn($a)=>array_sum(array_map(fn($t)=>(float)($t['profit_loss']??0),$a));return ['win_rate'=>count($closed)?round(count($wins)/count($closed)*100,1):0,'average_win'=>count($wins)?round($sum($wins)/count($wins),2):0,'average_loss'=>count($loss)?round($sum($loss)/count($loss),2):0,'profit_factor'=>abs($sum($loss))>0?round($sum($wins)/abs($sum($loss)),2):0,'conversion_rate'=>count($opps)?round(count(array_filter($opps,fn($o)=>($o['status']??'')==='approved'))/count($opps)*100,1):0];}}
